	/* (UUID(),'little-cat-tire-town-school-3','The Race','Cuộc đua','LITTLE_CAT_TIRE_TOWN_SCHOOL_3.mp3',NULL,'00:00:00.000','00:00:00.000','little-cat-tire-town-school',1,1,3) */
	('Tire Town School - Episode 3: The Race','Trường học Tire Town – Tập 3: Cuộc đua','00:00:01.800','00:00:06.800','little-cat-tire-town-school-3'),
	('"You like to race?" said Dipper','Dipper hỏi: "Cậu thích đua xe à?"','00:00:12.700','00:00:15.470','little-cat-tire-town-school-3'),
